<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Common\Application\Usecase\Install;

use Civi\Lughauth\Shared\Value\Random;
use Civi\Lughauth\Features\Document\Template\Domain\Gateway\TemplateWriteGateway;
use Civi\Lughauth\Features\Document\Template\Domain\Template;
use Civi\Lughauth\Features\Document\Template\Domain\TemplateAttributes;
use Civi\Lughauth\Features\Document\Template\Domain\TemplateChannelOptions;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\Gateway\TemplateVersionWriteGateway;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\TemplateVersion;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\TemplateVersionAttributes;

/**
 * Installation step that seeds the "user.login" mail template used to notify users of a
 * new sign-in to their account.
 *
 * This class is invoked once during the initial system installation by InstallUsecase. It
 * creates a Template entity with code "user.login" bound to the "corporate-mail" theme
 * and appends a TemplateVersion containing the HTML email body with Handlebars placeholders
 * for the user name ({{user.name}}), login date ({{login.date}}), and originating IP
 * address ({{login.ip}}).
 *
 * The template is enabled immediately after creation so it is ready for the notification
 * subsystem to dispatch on the first successful login event.
 */
class InstallLoginTemplate
{
    private const string CONTENT_DIR = __DIR__ . '/contents/';

    public function __construct(
        private readonly TemplateWriteGateway $templates,
        private readonly TemplateVersionWriteGateway $versions,
    ) {
    }

    /**
     * Creates and enables the "user.login" mail template along with its first version
     * containing the login-notification email body (contents/mail-login.html).
     */
    public function install(): void
    {
        $tpl = new TemplateAttributes();
        $tpl->uid(Random::comb());
        $tpl->code('user.login');
        $tpl->channel(TemplateChannelOptions::MAIL);
        $tpl->theme('corporate-mail');
        $tpl->enabled(true);
        $created = $this->templates->create(Template::create($tpl));
        $this->templates->update($created, $created->enable());

        $ver = new TemplateVersionAttributes();
        $ver->uid(Random::comb());
        $ver->template($created);
        $ver->subject('New sign-in to your account');
        $ver->contentHtml((string) file_get_contents(self::CONTENT_DIR . 'mail-login.html'));
        $this->versions->create(TemplateVersion::create($ver));
    }
}
